  'SOURCING_CRITERIA: ' + JSON.stringify(config.sourcingCriteria || {}) + '\n' +
  'COMPANY_FACTS: ' + JSON.stringify(config.companyFacts || {}) + '\n' +
  'BEGIN_UNTRUSTED_ITEMS\n' + lines + '\nEND_UNTRUSTED_ITEMS';

