  const patterns = [/\$\s?\d[\d,]*(?:\.\d+)?\s?[KkMm]?/g, /(?<![\d.$])\d{2,3}(?:,\d{3})+(?![\d%])|(?<![\d.$,])\d{2,}(?![\d%,])/g];
