.card .loc{font-family:var(--mono);font-size:9.5px;letter-spacing:.12em;text-transform:uppercase;color:var(--muted);margin-top:4px}
.pillars3{display:grid;grid-template-columns:1fr 1fr 1fr;gap:24px}
.slim{display:flex;align-items:baseline;gap:20px;padding:14px 0;border-bottom:1px solid var(--soft)}
.slim .t{flex:none;font-family:var(--mono);font-size:11px;font-weight:500;color:var(--gold-dk)}
.slim .t.c{color:var(--gray)}
.slim .w{font-size:12.5px;color:rgba(20,23,28,.7)}
.slim .w b{font-weight:600;color:var(--ink)}
.slim .when{font-family:var(--mono);font-size:9.5px;letter-spacing:.1em;text-transform:uppercase;color:var(--gray);white-space:nowrap}
.legend{display:grid;grid-template-columns:1fr 1.2fr 1fr;gap:40px;padding:20px 0 4px;border-bottom:1px solid var(--soft)}
.legend h3{font-family:var(--mono);font-size:9.5px;font-weight:500;letter-spacing:.2em;text-transform:uppercase;color:var(--ink);margin-bottom:10px}
.legend p,.legend li{font-size:11.5px;line-height:1.6;color:rgba(20,23,28,.7)}
.legend ul{list-style:none}
.legend li{display:flex;gap:10px;padding:2px 0}
.legend .lt{flex:none;width:16px;font-family:var(--mono);font-weight:500}
.foot{margin-top:16px;padding-top:14px;display:flex;align-items:center;gap:10px;font-family:var(--mono);font-size:9px;letter-spacing:.14em;text-transform:uppercase;color:var(--muted)}
.dot{width:6px;height:6px;background:var(--red)}
.countbar,.slim,.foot{flex-wrap:wrap}
/* Narrower than the 1280px sheet: the sheet shrinks and the grids stack, so no column
   is clipped or needs a sideways scroll. */
@media (max-width:1100px){
.card{grid-template-columns:120px 1fr;gap:16px 24px}
.card .pillars3,.card .srcline{grid-column:1/-1}
.legend{grid-template-columns:1fr 1fr;gap:24px 40px}
.legend>div:last-child{grid-column:1/-1}
}
@media (max-width:820px){
body{padding:24px 12px}
.sheet{padding:32px 24px 24px}
.masthead{flex-wrap:wrap;gap:12px}
.roleplate{text-align:left}
.hero{grid-template-columns:1fr}
.hero>.hex{grid-row:1}
.pillars2,.pillars3,.legend{grid-template-columns:1fr}
.countbar{gap:6px 16px}
}
@media (max-width:480px){
body{padding:0}
.sheet{padding:24px 16px 20px}
.masthead h1{font-size:30px}
.hero .co{font-size:30px}
.card{grid-template-columns:1fr}
}
@media print{body{background:#fff;padding:0}}
