<script>
(function(){
  var TIER={S:"#C8202E",A:"#1B3A2C",B:"#C7A24A",C:"rgba(20,23,28,.45)"};
  var RAD={H:1.0,M:0.6,L:0.25}, LBL=["OP","RO","PR","RG","SZ","ST"];
  function pt(cx,cy,r,i){var a=-Math.PI/2+i*Math.PI/3;return[cx+r*Math.cos(a),cy+r*Math.sin(a)];}
  function poly(cx,cy,r){var p=[];for(var i=0;i<6;i++){p.push(pt(cx,cy,r,i).map(function(n){return n.toFixed(1)}).join(","));}return p.join(" ");}
  document.querySelectorAll(".hex").forEach(function(el){
    var b=el.dataset.bands.split(","),t=el.dataset.tier,wc=el.dataset.wc!==undefined?parseInt(el.dataset.wc,10):-1;
    var w=parseInt(el.dataset.size||"120",10);
    var c=TIER[t],cx=50,cy=46,R=32;
    var s='<svg width="'+w+'" height="'+Math.round(w*0.94)+'" viewBox="0 0 100 94" role="img" aria-label="tier '+t+' fit profile">';
    [0.25,0.6,1.0].forEach(function(f){s+='<polygon points="'+poly(cx,cy,R*f)+'" fill="none" stroke="rgba(20,23,28,.15)" stroke-width="1"/>';});
    for(var i=0;i<6;i++){var p=pt(cx,cy,R,i);s+='<line x1="'+cx+'" y1="'+cy+'" x2="'+p[0].toFixed(1)+'" y2="'+p[1].toFixed(1)+'" stroke="rgba(20,23,28,.08)" stroke-width="1"/>';}
    var dp=[];for(var i=0;i<6;i++){dp.push(pt(cx,cy,R*RAD[b[i]],i).map(function(n){return n.toFixed(1)}).join(","));}
    s+='<polygon points="'+dp.join(" ")+'" fill="'+c+'" fill-opacity="0.13" stroke="'+c+'" stroke-width="1.6"/>';
    for(var i=0;i<6;i++){var v=pt(cx,cy,R*RAD[b[i]],i);
      if(i===wc){s+='<rect x="'+(v[0]-3.4).toFixed(1)+'" y="'+(v[1]-3.4).toFixed(1)+'" width="6.8" height="6.8" transform="rotate(45 '+v[0].toFixed(1)+' '+v[1].toFixed(1)+')" fill="#C7A24A"/>';}
      else{s+='<circle cx="'+v[0].toFixed(1)+'" cy="'+v[1].toFixed(1)+'" r="1.8" fill="'+c+'"/>';}}
    for(var i=0;i<6;i++){var L=pt(cx,cy,R+8,i);
      s+='<text x="'+L[0].toFixed(1)+'" y="'+(L[1]+2.4).toFixed(1)+'" text-anchor="middle" font-family="IBM Plex Mono,monospace" font-size="6.5" fill="rgba(20,23,28,.45)">'+LBL[i]+'</text>';}
    s+='<circle cx="'+cx+'" cy="'+cy+'" r="10.5" fill="#F7F7F4" stroke="'+c+'" stroke-width="1.4"/>';
    s+='<text x="'+cx+'" y="'+(cy+4.6)+'" text-anchor="middle" font-family="Gowun Batang,Georgia,serif" font-weight="700" font-size="13" fill="'+c+'">'+t+'</text>';
    s+='</svg>';
    el.innerHTML=s;
  });
})();
</script>
